$('[data-testid=auth-form]').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),body={username:f.get('username'),password:f.get('password'),display_name:f.get('display_name')};try{let x=await api(login?'/auth/login':'/auth/register',{method:'POST',body:JSON.stringify(body)});token=x.token;user=x.user;localStorage.setItem('huddle.token',token);showApp();await load()}catch(err){$('#auth-error').textContent=err.message}};
