$('#composer').onsubmit=async e=>{e.preventDefault();let i=$('#message-input');if(!i.value.trim())return;await api('/channels/'+channel.id+'/messages',{method:'POST',body:JSON.stringify({body:i.value})});i.value='';await selectChannel(channel)};
