THOUGHT: E.1 exposes focused message authorization, deletion-state, mention-refresh, and event behavior bugs. I’ll patch edit/delete to distinguish unknown, deleted, author/owner permissions, recompute mentions, and avoid repeat-delete events.

```mswea_bash_command
python3 - <<'PY'
p='/app/core.py'; s=open(p).read()
a=s.index('def edit_message('); b=s.index('def update_profile(',a)
new=r'''def edit_message(user,message_id,body):
    with tx() as c:
        r=c.execute("SELECT * FROM messages WHERE id=?",(message_id,)).fetchone()
        if not r: return ("notfound",None)
        if r["deleted"]: return ("deleted",None)
        ch=c.execute("SELECT * FROM channels WHERE id=?",(r["channel_id"],)).fetchone()
        if r["author_id"]!=user["id"]: return ("forbidden",None)
        mentions=resolve_mentions(c,body,ch,user["id"])
        c.execute("UPDATE messages SET body=?,edited_at=? WHERE id=?",(body,now_iso(),message_id))
        r=c.execute("SELECT * FROM messages WHERE id=?",(message_id,)).fetchone()
        obj=message_to_json(r); obj["mentions"]=mentions
        emit_event(c,r["channel_id"],"message.updated",{"message":obj})
        return ("ok",obj)

def delete_message(user,message_id):
    with tx() as c:
        r=c.execute("SELECT * FROM messages WHERE id=?",(message_id,)).fetchone()
        if not r: return ("notfound",False)
        if r["deleted"]: return ("ok",False)
        ch=c.execute("SELECT * FROM channels WHERE id=?",(r["channel_id"],)).fetchone()
        role=c.execute("SELECT role FROM workspace_members WHERE workspace_id=? AND user_id=?",(ch["workspace_id"],user["id"])).fetchone() if ch["workspace_id"] else None
        if r["author_id"]!=user["id"] and (not role or role["role"]!="owner"): return ("forbidden",False)
        c.execute("UPDATE messages SET deleted=1 WHERE id=?",(message_id,))
        emit_event(c,r["channel_id"],"message.deleted",{"message_id":message_id})
        return ("ok",True)

'''
s=s[:a]+new+s[b:]
open(p,'w').write(s)
p='/app/server.py'; s=open(p).read()
s=s.replace("    r=core.edit_message(u,int(request.match_info[\"id\"]),b[\"body\"])\n    return out({\"message\":r}) if r else json_error(403,\"forbidden\")",
'''    status,r=core.edit_message(u,int(request.match_info["id"]),b["body"])
    if status=="notfound": return json_error(404,"not found")
    if status=="deleted": return json_error(409,"deleted")
    if status!="ok": return json_error(403,"forbidden")
    return out({"message":r})''')
s=s.replace("    core.delete_message(u,int(request.match_info[\"id\"])); return out({\"deleted\":True})",
'''    status,deleted=core.delete_message(u,int(request.match_info["id"]))
    if status=="notfound": return json_error(404,"not found")
    if status!="ok": return json_error(403,"forbidden")
    return out({"deleted":True})''')
open(p,'w').write(s)
